package com.ruoyi.system.controller;

import com.ruoyi.common.annotation.Log;
import com.ruoyi.common.core.domain.AjaxResult;
import com.ruoyi.common.enums.BusinessType;
import com.ruoyi.common.exception.ServiceException;
import com.ruoyi.common.utils.SecurityUtils;
import com.ruoyi.system.shop.ShopRepository;
import java.math.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/miniapp/admin/finance-period")
@PreAuthorize("@ss.hasRole('admin') and @ss.hasPermi('system:finance:list')")
public class MiniAppFinancePeriodController {
 private final ShopRepository db;
 private final com.ruoyi.system.service.IEduFinanceExpenseService expenseService;
 public MiniAppFinancePeriodController(ShopRepository db,com.ruoyi.system.service.IEduFinanceExpenseService expenseService){this.db=db;this.expenseService=expenseService;}
 private record Period(LocalDate start,LocalDate end) {}
 private Period period(String begin,String end){try{LocalDate a=LocalDate.parse(begin),b=LocalDate.parse(end);if(a.isAfter(b)||ChronoUnit.DAYS.between(a,b)>1095)throw new IllegalArgumentException();return new Period(a,b);}catch(Exception e){throw new ServiceException("请选择有效日期范围（最长三年）");}}
 private BigDecimal number(Object value){return value==null?BigDecimal.ZERO:new BigDecimal(value.toString());}
 private BigDecimal prorate(BigDecimal amount,YearMonth month,Period p){LocalDate a=month.atDay(1).isAfter(p.start)?month.atDay(1):p.start,b=month.atEndOfMonth().isBefore(p.end)?month.atEndOfMonth():p.end;long days=ChronoUnit.DAYS.between(a,b)+1;return amount.multiply(BigDecimal.valueOf(days)).divide(BigDecimal.valueOf(month.lengthOfMonth()),2,RoundingMode.HALF_UP);}
 private List<Map<String,Object>> salaries(Period p){var rows=db.rows("SELECT record_id,teacher_id,teacher_name,salary_month,total_amount,confirm_status FROM edu_teacher_salary_record WHERE del_flag='0' AND salary_month BETWEEN ? AND ? ORDER BY salary_month DESC,teacher_name,record_id",YearMonth.from(p.start).toString(),YearMonth.from(p.end).toString());for(var r:rows)r.put("periodAmount",prorate(number(r.get("totalAmount")),YearMonth.parse(r.get("salaryMonth").toString()),p).toPlainString());return rows;}
 @GetMapping
 public AjaxResult summary(@RequestParam String beginDate,@RequestParam String endDate){Period p=period(beginDate,endDate);var lessons=db.one("SELECT COALESCE(SUM(p.amount),0) contract_amount,COALESCE(SUM(p.amount-COALESCE(r.refund_amount,0)),0) confirmed_amount,COALESCE(SUM(r.refund_amount),0) refund_amount FROM edu_tuition_payment p LEFT JOIN (SELECT payment_id,SUM(approved_amount) refund_amount FROM edu_tuition_refund WHERE refund_status='SUCCESS' GROUP BY payment_id) r ON r.payment_id=p.payment_id WHERE p.payment_status='SUCCESS' AND p.paid_time>=? AND p.paid_time<?",p.start.atStartOfDay(),p.end.plusDays(1).atStartOfDay());var shop=db.one("SELECT COALESCE(SUM(CASE WHEN order_status<>'CLOSED' THEN payable_amount ELSE 0 END),0) contract_amount,COALESCE(SUM(CASE WHEN pay_status='1' THEN payable_amount-refunded_amount ELSE 0 END),0) confirmed_amount,COALESCE(SUM(CASE WHEN pay_status IN ('1','2') THEN COALESCE(refunded_amount,0) ELSE 0 END),0) refund_amount FROM edu_material_order WHERE del_flag='0' AND create_time>=? AND create_time<?",p.start.atStartOfDay(),p.end.plusDays(1).atStartOfDay());BigDecimal contract=number(lessons.get("contractAmount")).add(number(shop.get("contractAmount"))),income=number(lessons.get("confirmedAmount")).add(number(shop.get("confirmedAmount"))),refund=number(lessons.get("refundAmount")).add(number(shop.get("refundAmount"))),salary=salaries(p).stream().map(r->number(r.get("periodAmount"))).reduce(BigDecimal.ZERO,BigDecimal::add),expense=number(db.one("SELECT COALESCE(SUM(amount),0) amount FROM edu_finance_expense WHERE del_flag='0' AND expense_date>=? AND expense_date<?",p.start,p.end.plusDays(1)).get("amount"));Map<String,Object> summary=new LinkedHashMap<>();summary.put("contractAmount",contract);summary.put("confirmedRevenue",income);summary.put("refundTotal",refund);summary.put("receivable",contract.subtract(income));summary.put("teacherSalary",salary);summary.put("expenseTotal",expense);summary.put("grossProfit",income.subtract(salary));summary.put("netProfit",income.subtract(salary).subtract(expense));return AjaxResult.success(Map.of("beginDate",beginDate,"endDate",endDate,"summary",summary,"revenueBySource",List.of(Map.of("name","课时费","value",lessons.get("confirmedAmount")),Map.of("name","资料商城","value",shop.get("confirmedAmount")))));}
 @PreAuthorize("@ss.hasRole('admin') and @ss.hasPermi('system:finance:list') and @ss.hasPermi('system:salaryRecord:list')") @GetMapping("/salaries")
 public AjaxResult salaryList(@RequestParam String beginDate,@RequestParam String endDate){Period p=period(beginDate,endDate);var rows=salaries(p);var teachers=db.rows("SELECT DISTINCT u.user_id teacher_id,u.user_name teacher_name FROM sys_user u JOIN sys_user_role ur ON ur.user_id=u.user_id JOIN sys_role r ON r.role_id=ur.role_id WHERE u.del_flag='0' AND u.status='0' AND r.role_key='teacher' AND r.status='0' AND r.del_flag='0'");Set<String> existing=new HashSet<>();for(var r:rows)existing.add(r.get("teacherId")+":"+r.get("salaryMonth"));for(YearMonth m=YearMonth.from(p.start);!m.isAfter(YearMonth.from(p.end));m=m.plusMonths(1))for(var t:teachers)if(!existing.contains(t.get("teacherId")+":"+m)) {Map<String,Object> row=new LinkedHashMap<>();row.put("teacherId",t.get("teacherId"));row.put("teacherName",t.get("teacherName"));row.put("salaryMonth",m.toString());row.put("missing",true);rows.add(row);}return AjaxResult.success(rows);}
 public record SalaryEdit(BigDecimal amount,BigDecimal expectedAmount) {}
 public record SalaryCreate(Long teacherId,String salaryMonth,BigDecimal amount) {}
 @PreAuthorize("@ss.hasRole('admin') and @ss.hasPermi('system:finance:list') and @ss.hasPermi('system:salaryRecord:add') and @ss.hasPermi('system:salaryRecord:edit')") @PostMapping("/salary") @Log(title="看板新增教师月工资",businessType=BusinessType.INSERT)
 @Transactional(rollbackFor=Exception.class)
 public AjaxResult createSalary(@RequestBody SalaryCreate body){if(body==null||body.teacherId()==null||body.salaryMonth()==null||!body.salaryMonth().matches("\\d{4}-(0[1-9]|1[0-2])")||body.amount()==null||body.amount().signum()<0||body.amount().scale()>2||body.amount().compareTo(new BigDecimal("99999999.99"))>0)throw new ServiceException("请输入有效工资金额");var teacher=db.rows("SELECT DISTINCT u.user_id,u.user_name FROM sys_user u JOIN sys_user_role ur ON ur.user_id=u.user_id JOIN sys_role r ON r.role_id=ur.role_id WHERE u.user_id=? AND u.del_flag='0' AND u.status='0' AND r.role_key='teacher' AND r.status='0' AND r.del_flag='0'",body.teacherId());if(teacher.isEmpty())throw new ServiceException("教师不存在或已停用");try{db.jdbc().update("INSERT INTO edu_teacher_salary_record(teacher_id,teacher_name,salary_month,total_amount,confirm_status,del_flag,create_by,create_time,remark) VALUES(?,?,?,?,'0','0',?,NOW(),'看板手工录入总额，明细未拆分')",body.teacherId(),teacher.get(0).get("userName"),body.salaryMonth(),body.amount(),SecurityUtils.getUsername());}catch(org.springframework.dao.DuplicateKeyException e){throw new ServiceException("该教师本月已有记录，请刷新后核对");}return AjaxResult.success();}
 @PreAuthorize("@ss.hasRole('admin') and @ss.hasPermi('system:finance:list') and @ss.hasPermi('system:salaryRecord:edit')") @PutMapping("/salary/{id}") @Log(title="看板修改教师月工资",businessType=BusinessType.UPDATE)
 @Transactional(rollbackFor=Exception.class)
 public AjaxResult editSalary(@PathVariable Long id,@RequestBody SalaryEdit body){if(body==null||body.amount()==null||body.expectedAmount()==null||body.amount().signum()<0||body.amount().scale()>2||body.amount().compareTo(new BigDecimal("99999999.99"))>0)throw new ServiceException("请输入有效工资金额");int n=db.jdbc().update("UPDATE edu_teacher_salary_record SET total_amount=?,update_by=?,update_time=NOW() WHERE record_id=? AND del_flag='0' AND total_amount=?",body.amount(),SecurityUtils.getUsername(),id,body.expectedAmount());if(n!=1)throw new ServiceException("工资记录已变化或不存在，请刷新后重试");return AjaxResult.success();}
 @PreAuthorize("@ss.hasRole('admin') and @ss.hasPermi('system:finance:list') and @ss.hasPermi('system:expense:list')") @GetMapping("/expenses")
 public AjaxResult expenses(@RequestParam String beginDate,@RequestParam String endDate){Period p=period(beginDate,endDate);return AjaxResult.success(db.rows("SELECT expense_id,title,expense_type,amount,detail,DATE_FORMAT(expense_date,'%Y-%m-%d') expense_date FROM edu_finance_expense WHERE del_flag='0' AND expense_date>=? AND expense_date<? ORDER BY expense_date DESC,expense_id DESC",p.start,p.end.plusDays(1)));}
 public record ExpenseEdit(BigDecimal amount,BigDecimal expectedAmount) {}
 public record ExpenseCreate(String title,String expenseDate,BigDecimal amount,String expenseType,String detail) {}
 @PreAuthorize("@ss.hasRole('admin') and @ss.hasPermi('system:finance:list') and @ss.hasPermi('system:expense:add')") @GetMapping("/expense-types")
 public AjaxResult expenseTypes(){return AjaxResult.success(db.rows("SELECT dict_label,dict_value FROM sys_dict_data WHERE dict_type='edu_expense_type' AND status='0' ORDER BY dict_sort,dict_code"));}
 @PreAuthorize("@ss.hasRole('admin') and @ss.hasPermi('system:finance:list') and @ss.hasPermi('system:expense:add')") @PostMapping("/expense") @Log(title="看板新增成本支出",businessType=BusinessType.INSERT)
 public AjaxResult createExpense(@RequestBody ExpenseCreate body){if(body==null||(body.title()!=null&&body.title().trim().length()>100)||body.amount()==null||body.amount().signum()<0||body.amount().scale()>2||body.amount().compareTo(new BigDecimal("99999999.99"))>0||(body.detail()!=null&&body.detail().trim().length()>500))throw new ServiceException("金额或文本长度无效");LocalDate date;try{date=LocalDate.parse(body.expenseDate());}catch(Exception e){throw new ServiceException("日期无效");}if(body.expenseType()==null||db.rows("SELECT dict_code FROM sys_dict_data WHERE dict_type='edu_expense_type' AND status='0' AND dict_value=?",body.expenseType()).isEmpty())throw new ServiceException("请选择有效的支出类型");var expense=new com.ruoyi.system.domain.EduFinanceExpense();expense.setTitle(body.title()==null?"":body.title().trim());expense.setExpenseType(body.expenseType());expense.setDetail(body.detail()==null?"":body.detail().trim());expense.setAmount(body.amount());expense.setExpenseDate(java.util.Date.from(date.atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant()));if(expenseService.insertExpense(expense)!=1)throw new ServiceException("成本保存失败");return AjaxResult.success();}
 @PreAuthorize("@ss.hasRole('admin') and @ss.hasPermi('system:finance:list') and @ss.hasPermi('system:expense:edit')") @PutMapping("/expense/{id}") @Log(title="看板修改成本支出",businessType=BusinessType.UPDATE)
 public AjaxResult editExpense(@PathVariable Long id,@RequestBody ExpenseEdit body){if(body==null||body.amount()==null||body.expectedAmount()==null||body.amount().signum()<0||body.amount().scale()>2||body.amount().compareTo(new BigDecimal("99999999.99"))>0)throw new ServiceException("请输入有效成本金额");int n=db.jdbc().update("UPDATE edu_finance_expense SET amount=?,update_by=?,update_time=NOW() WHERE expense_id=? AND del_flag='0' AND amount=?",body.amount(),SecurityUtils.getUsername(),id,body.expectedAmount());if(n!=1)throw new ServiceException("成本记录已变化或不存在，请刷新后重试");return AjaxResult.success();}
}
